1	import { ReplitConnectors } from "@replit/connectors-sdk";
2	
3	const connectors = new ReplitConnectors();
4	
5	const MAX_RATE_LIMIT_RETRIES = 5;
6	const RATE_LIMIT_BASE_DELAY_MS = 500;
7	
8	function sleep(ms: number): Promise<void> {
9	  return new Promise((resolve) => setTimeout(resolve, ms));
10	}
11	
12	export async function todoistRequest(
13	  method: string,
14	  path: string,
15	  body?: unknown,
16	): Promise<unknown> {
17	  for (let attempt = 0; ; attempt++) {
18	    const response = await connectors.proxy("todoist", path, {
19	      method,
20	      body: body !== undefined ? JSON.stringify(body) : undefined,
21	      headers: body !== undefined ? { "Content-Type": "application/json" } : undefined,
22	    });
23	
24	    if (response.status === 404) return null;
25	    if (!response.ok) {
26	      if (response.status === 429 && attempt < MAX_RATE_LIMIT_RETRIES) {
27	        const delay = RATE_LIMIT_BASE_DELAY_MS * 2 ** attempt + Math.random() * 250;
28	        await sleep(delay);
29	        continue;
30	      }
31	      const text = await response.text();
32	      throw new Error(`Todoist API error ${response.status}: ${text}`);
33	    }
34	    if (response.status === 204) return {};
35	    return response.json();
36	  }
37	}
38	
39	export async function todoistListProjects(): Promise<{ id: string; name: string }[]> {
40	  const data = await todoistRequest("GET", "/api/v1/projects") as { results?: { id: string; name: string }[] } | null;
41	  return data?.results ?? [];
42	}
