    return;
  }

  const parsed = BulkCreateEblastsBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: parsed.error.message });
    return;
  }

  if (parsed.data.eblasts.length === 0) {
    res.status(201).json([]);
    return;
  }

  const eblasts = await db
    .insert(eblastsTable)
    .values(parsed.data.eblasts.map((e) => ({ ...e, showId: params.data.showId })))
    .returning();

  res.status(201).json(eblasts);
});

router.put("/:eblastId", async (req, res): Promise<void> => {
  const params = UpdateEblastParams.safeParse({
    showId: Number(req.params.showId),
    eblastId: Number(req.params.eblastId),
  });
  if (!params.success) {
    res.status(400).json({ error: "Invalid params" });
    return;
  }

  const body = { ...req.body };
  if (body.dueDate === "") body.dueDate = null;

  const parsed = UpdateEblastBody.safeParse(body);
  if (!parsed.success) {
    res.status(400).json({ error: parsed.error.message });
    return;
  }

  const updates: Record<string, unknown> = { ...parsed.data };

  if (parsed.data.sent === true) {
    updates.sentAt = parsed.data.sentAt ? new Date(parsed.data.sentAt) : new Date();
  } else if (parsed.data.sent === false) {
    updates.sentAt = null;
  } else if (parsed.data.sentAt !== undefined) {
    updates.sentAt = parsed.data.sentAt ? new Date(parsed.data.sentAt) : null;
  }

  const [eblast] = await db
    .update(eblastsTable)
    .set(updates)
    .where(
      and(
        eq(eblastsTable.id, params.data.eblastId),
        eq(eblastsTable.showId, params.data.showId)
      )
    )
    .returning();

  if (!eblast) {
    res.status(404).json({ error: "E-blast not found" });
    return;
  }

  res.json(eblast);
});

router.delete("/:eblastId", async (req, res): Promise<void> => {
  const params = DeleteEblastParams.safeParse({
    showId: Number(req.params.showId),
    eblastId: Number(req.params.eblastId),
  });
  if (!params.success) {
    res.status(400).json({ error: "Invalid params" });
    return;
  }

  const [eblast] = await db
    .select({ gcalEventId: eblastsTable.gcalEventId, todoistTaskId: eblastsTable.todoistTaskId })
    .from(eblastsTable)
    .where(and(eq(eblastsTable.id, params.data.eblastId), eq(eblastsTable.showId, params.data.showId)));

  if (eblast?.gcalEventId) {
    await db.insert(gcalOrphansTable).values({ gcalEventId: eblast.gcalEventId, calendarType: "eblast" });
  }
  if (eblast?.todoistTaskId) {
    await db.insert(todoistOrphansTable).values({ todoistTaskId: eblast.todoistTaskId, itemType: "eblast" });
  }

  await db
    .delete(eblastsTable)
    .where(
      and(
        eq(eblastsTable.id, params.data.eblastId),
        eq(eblastsTable.showId, params.data.showId)
      )
    );

  res.status(204).send();
});

export default router;

import { sql } from "drizzle-orm";
import {
  pgTable,
  text,
  serial,
  integer,
  timestamp,
  jsonb,
  index,
  uniqueIndex,
} from "drizzle-orm/pg-core";

// Durable outbound outbox for Todoist delivery.
//
// Created in this migration but not yet read or written by any route — the existing
// manual sync path and `todoist_orphans` continue to operate unchanged until Phase 2.
//
// Model: one *coalesced* active row per item carrying that item's current state, rather
// than a replay log of individual operations. `operation` is the delivery shape actually
// performed against the Todoist API; `reason` is audit metadata recording what triggered it.
export const todoistSyncEventsTable = pgTable(
  "todoist_sync_events",
  {
    id: serial("id").primaryKey(),
    // 'task' | 'eblast'
    itemType: text("item_type").notNull(),
    // Polymorphic (points at either tasks.id or eblasts.id) and null for deletes whose
    // local row is already gone — so it intentionally carries no foreign key.
    itemId: integer("item_id"),
    todoistTaskId: text("todoist_task_id"),
    // Delivery shape: 'upsert' | 'delete'
    operation: text("operation").notNull(),
    // Audit only: 'create' | 'update' | 'complete' | 'reopen' | 'delete' | 'unlink'
    reason: text("reason").notNull(),
    // 'pending' | 'in_progress' | 'delivered' | 'failed' | 'abandoned'
    status: text("status").notNull().default("pending"),
    attemptCount: integer("attempt_count").notNull().default(0),
    nextAttemptAt: timestamp("next_attempt_at", { withTimezone: true }).notNull().defaultNow(),
    claimedAt: timestamp("claimed_at", { withTimezone: true }),
    payloadSnapshot: jsonb("payload_snapshot"),
    lastError: text("last_error"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("todoist_sync_events_due_idx").on(table.status, table.nextAttemptAt),
    // At most one active event per live local item.
    uniqueIndex("todoist_sync_events_item_active")
      .on(table.itemType, table.itemId)
      .where(
        sql`${table.itemId} is not null and ${table.status} in ('pending', 'in_progress')`,
      ),
    // At most one active delete per already-unlinked remote task. Separate from the index
    // above because Postgres treats NULLs as distinct, so a single (item_type, item_id)
    // index would not deduplicate rows whose item_id is NULL.
    uniqueIndex("todoist_sync_events_delete_active")
      .on(table.itemType, table.todoistTaskId)
      .where(
        sql`${table.itemId} is null and ${table.operation} = 'delete' and ${table.status} in ('pending', 'in_progress')`,
      ),
  ],
);

import { pgTable, text, timestamp } from "drizzle-orm/pg-core";

// Server-side replacement for the browser-local `todoist_prefs` localStorage key.
// The app has no user/auth/workspace model, so this is a singleton row — but it is
// keyed by a text id (rather than a bare one-row table) so an ownership scope can be
// introduced later without renumbering or restructuring.
export const TODOIST_SETTINGS_ID = "default";

export const todoistSettingsTable = pgTable("todoist_settings", {
  id: text("id").primaryKey().default(TODOIST_SETTINGS_ID),
  taskProjectId: text("task_project_id"),
  eblastProjectId: text("eblast_project_id"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

