  const body = makeTodoistTask(content, descParts.join("\n"), eblast.dueDate, projectId);

  let todoistTaskId = eblast.todoistTaskId;
  if (todoistTaskId) {
    const result = await todoistRequest("POST", `/api/v1/tasks/${todoistTaskId}`, body);
    if (result === null) {
      todoistTaskId = null;
    } else {
      counters.updated++;
    }
