async function drainOrphans(counters: { deleted: number }) {
  const orphans = await db.select().from(todoistOrphansTable);
  if (orphans.length === 0) return;

  const CONCURRENCY = 5;
  for (let i = 0; i < orphans.length; i += CONCURRENCY) {
