export interface SyncCounters {
  created: number;
  updated: number;
  deleted: number;
}

// Maps a typed delivery outcome onto the manual route's existing
// { created, updated, deleted } response shape. `skipped_no_due_date` and
// `failed` are intentionally not tallied — they were never counted under the
// legacy behavior either. `unlinked_remote_missing` is not tallied as
// `deleted`: nothing was deleted from Todoist (it was already gone), so
// counting it as a delete would overstate what actually happened.
export function tallyOutcome(counters: SyncCounters, outcome: DeliveryOutcome): void {
  if (outcome === "created") counters.created++;
  else if (outcome === "updated") counters.updated++;
  else if (outcome === "deleted") counters.deleted++;
}

